1: package Zonemaster::GUI::Dancer::Export;
2: 
3: use warnings;
4: use 5.14.2;
5: 
6: use Dancer ':syntax';
7: use Plack::Builder;
8: use HTML::Entities;
9: use Zonemaster::GUI::Dancer::Client;
10: 
11: our $VERSION = '1.0.5';
12: 
13: my $backend_port = 5000;
14: $backend_port = $ENV{ZONEMASTER_BACKEND_PORT} if ($ENV{ZONEMASTER_BACKEND_PORT});
15: my $url = "http://localhost:$backend_port";
16: 
17: any [ 'get', 'post' ] => '/export' => sub {
18:     header( 'Cache-Control' => 'no-store, no-cache, must-revalidate' );
19:     my %allparams = params;
20:     no warnings 'uninitialized';
21: 
22:     if ( $allparams{'type'} eq 'HTML' ) {
23: 		my $c = Zonemaster::GUI::Dancer::Client->new( { url => $url } );
24: 		my $test_result = $c->get_test_results( { id => $allparams{'test_id'}, language => $allparams{'lang'} } );
25: 
26: 		my @test_results;
27: 		my $previous_module = '';
28: 		foreach my $result ( @{ $test_result->{results} } ) {
29: 			if ( $previous_module ne $result->{module} ) {
30: 				push( @test_results, { is_module => 1, message => $result->{module} } );
31: 				$previous_module = $result->{module};
32: 			}
33: 
34: 			push( @test_results, { is_module => 0, message => $result->{message}, class => "alert alert-$result->{level}" } );
35: 		}
36: 
37: 		my $template_params;
38: 		$template_params->{test_results}  = \@test_results;
39: 		template 'export', $template_params, { layout => undef };
40:     }
41: };
42: 
43: true;

